{
  "name": "文件夹图像采集源",
  "name_en": "Folder Image Capture Source",
  "manufacturer": "",
  "description": "一种基于文件夹的图像输入源，可将磁盘中的图像文件按名称或创建时间顺序作为连续视频流读取，并可监视文件夹中的新增或删除图像。适用于实验室中回放已采集的显微图像或相机图像、测试图像处理流程，以及在无实体相机时模拟视频输入。",
  "description_en": "A folder-based image input source that reads image files from disk as a continuous video stream, ordered by filename or creation time, and can monitor the folder for added or removed images. It is useful in laboratories for replaying previously acquired microscope or camera images, testing image-processing workflows, and simulating a video input when no physical camera is connected.",
  "tag_hints": [
    "file-based video source",
    "image sequence playback",
    "folder monitoring",
    "virtual camera input",
    "offline image replay",
    "image processing testing"
  ],
  "actions": [
    {
      "action_name": "auto-start_async",
      "description": "启动后台图像采集线程，持续更新最新帧。",
      "description_en": "Start the background image capture thread and continuously update the latest frame."
    },
    {
      "action_name": "auto-stop",
      "description": "停止后台图像采集线程。",
      "description_en": "Stop the background image capture thread."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到文件夹图像源并加载图像文件列表。",
      "description_en": "Connect to the folder image source and load the image file list."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开文件夹图像源连接并停止文件夹监视。",
      "description_en": "Disconnect from the folder image source and stop folder watching."
    },
    {
      "action_name": "auto-set_exposure",
      "description": "设置曝光参数。",
      "description_en": "Set the exposure setting."
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置增益参数。",
      "description_en": "Set the gain setting."
    },
    {
      "action_name": "auto-enable_auto_exposure",
      "description": "启用或禁用自动曝光。",
      "description_en": "Enable or disable auto exposure."
    },
    {
      "action_name": "auto-set_frame_size",
      "description": "设置帧尺寸。",
      "description_en": "Set the frame size."
    },
    {
      "action_name": "auto-set_fps",
      "description": "设置帧率。",
      "description_en": "Set the frame rate."
    },
    {
      "action_name": "auto-set_current_index",
      "description": "设置当前图像文件索引。",
      "description_en": "Set the current image file index."
    },
    {
      "action_name": "auto-validate_file_list",
      "description": "校验图像文件列表并移除缺失文件。",
      "description_en": "Validate the image file list and remove missing files."
    },
    {
      "action_name": "auto-enable_folder_watching",
      "description": "启用或禁用文件夹监视。",
      "description_en": "Enable or disable folder watching."
    },
    {
      "action_name": "auto-is_folder_watching_enabled",
      "description": "检查文件夹监视是否已启用。",
      "description_en": "Check whether folder watching is enabled."
    },
    {
      "action_name": "auto-force_refresh",
      "description": "手动刷新图像文件列表。",
      "description_en": "Manually refresh the image file list."
    }
  ]
}

